// Builds the Telegram price table from REAL numbers, and the prompt for the model.
// Deliberate split: the table is produced here, in code, from the tracker's own
// data. The model only writes prose around it and is never the source of a
// figure - a hallucinated price in a money alert is the one failure mode that
// must be impossible by construction rather than by prompting.
const s = $json;
const coins = (s.coins || []).filter(c => typeof c.price === 'number');
if (!coins.length) {
  throw new Error('crypto tracker returned no prices - is the feed connected?');
}

const fmt = (p) => {
  if (typeof p !== 'number') return 'n/a';
  if (p >= 1000) return p.toLocaleString('en-US', { maximumFractionDigits: 0 });
  if (p >= 1) return p.toFixed(2);
  return p.toPrecision(4);
};
const pct = (v) => `${v >= 0 ? '+' : ''}${v.toFixed(2)}%`;

const sorted = [...coins].sort((a, b) => (b.change24h ?? 0) - (a.change24h ?? 0));

const table = sorted.map(c => {
  const ch = c.change24h ?? 0;
  const mark = ch > 0 ? '🟢' : ch < 0 ? '🔴' : '⚪';
  const warn = (c.health && c.health !== 'ok') ? ' ⚠️' : '';
  return `${mark} <b>${c.ticker}</b>  $${fmt(c.price)}  (${pct(ch)})${warn}`;
}).join('\n');

const facts = sorted.map(c =>
  `${c.ticker}: $${fmt(c.price)}, 24ч ${pct(c.change24h ?? 0)}, макс $${fmt(c.high)}, мин $${fmt(c.low)}`
).join('\n');

// Ranking and averaging are arithmetic, so code does them and hands the model the
// conclusion. Asked to work it out itself, an 8B model gets it subtly wrong - it
// called XMR (+2.17%) the leader over ETH (+2.20%) - and prose that contradicts
// the table printed directly above it is worse than no prose at all.
const best = sorted[0];
const worst = sorted[sorted.length - 1];
const avg = sorted.reduce((a, c) => a + (c.change24h ?? 0), 0) / sorted.length;
const up = sorted.filter(c => (c.change24h ?? 0) > 0).length;
const verdict = `Лидер роста: ${best.ticker} (${pct(best.change24h ?? 0)}). ` +
  `Лидер падения: ${worst.ticker} (${pct(worst.change24h ?? 0)}). ` +
  `В плюсе: ${up} из ${sorted.length}. Среднее изменение: ${pct(avg)}.`;

// Events are stored as ready-to-send Telegram messages: multi-line and full of
// HTML. Pasting them in verbatim feeds the model a wall of markup AND the price
// table of *yesterday's* summary - stale figures it will happily repeat as
// current. So: drop previous summaries, strip tags, keep one line each.
const dayAgo = Math.floor(Date.now() / 1000) - 86400;
const alerts = (s.events || [])
  .filter(e => e.ts >= dayAgo && e.kind !== 'system' && e.kind !== 'summary')
  .slice(0, 15)
  .map(e => {
    const one = String(e.message || '')
      .replace(/<[^>]*>/g, '')
      .replace(/\s*\n+\s*/g, ' · ')
      .replace(/\s{2,}/g, ' ')
      .trim();
    return '- ' + (one.length > 140 ? one.slice(0, 137) + '…' : one);
  });

const halted = coins
  .filter(c => c.health && c.health !== 'ok')
  .map(c => `${c.ticker} (${c.health_note || c.health})`);

const system = [
  'Ты финансовый аналитик. Пиши по-русски, деловым тоном.',
  'Используй ТОЛЬКО те числа, которые даны во входных данных.',
  'Никогда не придумывай цены, проценты и события.',
  'Формат: 4-6 предложений сплошным текстом, без markdown и без эмодзи.',
  'Пиши только по-русски: никаких английских слов, кроме тикеров монет.',
  'Не перечисляй все монеты подряд — таблица с ценами уже есть отдельно.',
].join(' ');

const user = [
  'Рыночные данные за последние 24 часа:',
  facts,
  '\nУже посчитано, используй как есть и не пересчитывай: ' + verdict,
  alerts.length
    ? '\nСработавшие оповещения за сутки:\n' + alerts.join('\n')
    : '\nОповещений за сутки не было.',
  halted.length ? '\nПроблемы с данными: ' + halted.join(', ') : '',
].filter(Boolean).join('\n');

return [{ json: { system, user, table, count: coins.length } }];

// Accepts either shape: Ollama returns {message:{content}}, OpenAI-compatible
// APIs (OpenRouter) return {choices:[{message:{content}}]}. Handling both is
// what lets the model be swapped without touching anything downstream.
const r = $json;
const raw = (r?.message?.content ?? r?.choices?.[0]?.message?.content ?? '').trim();
if (!raw) {
  throw new Error('LLM returned no text: ' + JSON.stringify(r).slice(0, 300));
}

// Telegram parses this message as HTML. A stray tag from the model would make
// the whole send fail with "can't parse entities", so strip them.
const comment = raw.replace(/<[^>]*>/g, '').trim();

const p = $('Build prompt').first().json;
const day = new Date().toLocaleDateString('ru-RU', {
  day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Europe/Oslo',
});

const text = [
  `📊 <b>Криптосводка за 24 часа</b> — ${day}`,
  '',
  p.table,
  '',
  '💬 <i>' + comment + '</i>',
].join('\n');

return [{ json: { text } }];
